CREATE TABLE alfred_snapshot(id uuid PRIMARY KEY,series_id text NOT NULL,as_of date NOT NULL,observation_start date NOT NULL,observation_end date NOT NULL,response_id uuid NOT NULL REFERENCES official_response(id),collected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alfred_observation(snapshot_id uuid NOT NULL REFERENCES alfred_snapshot(id),observation_date date NOT NULL,value numeric,realtime_start date NOT NULL,realtime_end date NOT NULL,PRIMARY KEY(snapshot_id,observation_date,realtime_start),CHECK(realtime_end>=realtime_start));
CREATE VIEW unified_macro_observation AS
 SELECT 'ECB_DATA'::text source_id,m.series_id,m.observation_date,m.value,s.units,r.collected_at acquired_at,NULL::date source_realtime_start,m.evidence_id proof_id,r.raw_content_hash response_hash,'SAVED_CURRENT_RESPONSE'::text ledger_kind FROM macro_observation m JOIN macro_series s ON s.id=m.series_id JOIN raw_evidence r ON r.id=m.evidence_id
 UNION ALL SELECT 'FRED',f.series_id,f.observation_date,f.value,f.units,f.acquired_at,f.realtime_start,f.evidence_id,r.raw_content_hash,'FRED_RESPONSE' FROM fred_observation f JOIN raw_evidence r ON r.id=f.evidence_id
 UNION ALL SELECT 'ECB_DATA',h.series_id,h.observation_date,h.value,s.units,h.collected_at,NULL::date,h.response_id,r.sha256,'HISTORY_QUERY' FROM macro_history_version h JOIN macro_series s ON s.id=h.series_id JOIN official_response r ON r.id=h.response_id WHERE h.action<>'Delete';
